import fs from 'fs';
import { TorusGeometry } from 'three';
import { MeshBVH, SAH } from 'three-mesh-bvh';

// The bundled worker scripts are generated by "npm run build" and loaded into a Worker through a blob
// url when the worker module can't be loaded. Running them in a Worker is covered by Workers.test.js,
// these tests check that they're self-contained classic scripts built from the current source.
function readBundledWorker( name ) {

	return fs.readFileSync( new URL( `../src/workers/${ name }.bundled.worker.js`, import.meta.url ), 'utf8' );

}

// evaluates the script as a classic script with a stand-in for the worker global scope
function evaluateWorkerScript( code ) {

	const messages = [];
	const scope = {
		onmessage: null,
		postMessage: data => messages.push( data ),
	};

	new Function( 'self', code )( scope );
	return { scope, messages };

}

describe( 'Bundled workers', () => {

	for ( const name of [ 'generateMeshBVH', 'parallelMeshBVH' ] ) {

		describe( `${ name }.bundled.worker.js`, () => {

			it( 'should be a classic script with no imports.', () => {

				const code = readBundledWorker( name );

				// "import" and "export" statements and "import.meta" don't parse outside of a module
				expect( () => new Function( code ) ).not.toThrow();
				expect( code ).not.toMatch( /\bimport\s*\(/ );

			} );

			it( 'should post the ready message once evaluated.', () => {

				const { scope, messages } = evaluateWorkerScript( readBundledWorker( name ) );
				expect( messages ).toEqual( [ { type: 'ready' } ] );
				expect( typeof scope.onmessage ).toBe( 'function' );

			} );

		} );

	}

	describe( 'generateMeshBVH.bundled.worker.js output', () => {

		function generate( geometry, options ) {

			const { scope, messages } = evaluateWorkerScript( readBundledWorker( 'generateMeshBVH' ) );
			scope.onmessage( {
				data: {
					index: geometry.index.array,
					position: geometry.attributes.position.array,
					options: {
						...options,
						groups: [ ...geometry.groups ],
					},
				},
			} );

			return messages[ messages.length - 1 ];

		}

		const geometry = new TorusGeometry( 5, 5, 50, 100 );
		const groupGeometry = geometry.clone();
		const third = groupGeometry.index.count / 3;
		groupGeometry.addGroup( 0, third, 0 );
		groupGeometry.addGroup( third, third, 1 );
		groupGeometry.addGroup( third * 2, third, 2 );

		const cases = [
			[ 'default options', geometry, {} ],
			[ 'SAH', geometry, { strategy: SAH } ],
			[ 'groups', groupGeometry, {} ],
			[ 'groups and indirect', groupGeometry, { indirect: true } ],
		];

		for ( const [ desc, geometry, options ] of cases ) {

			it( `should build the same BVH as MeshBVH with ${ desc }.`, () => {

				const result = generate( geometry.clone(), options );
				const expected = MeshBVH.serialize( new MeshBVH( geometry.clone(), options ) );
				const { serialized } = result;

				expect( result.error ).toBe( null );
				expect( serialized.roots.map( r => new Uint8Array( r ) ) ).toEqual( expected.roots.map( r => new Uint8Array( r ) ) );
				expect( serialized.index ).toEqual( expected.index );
				expect( serialized.indirectBuffer ).toEqual( expected.indirectBuffer );

			} );

		}

	} );

} );
